import re

def tokenize(expr: str) -> list[str]:
    # Remove all whitespace
    expr = expr.replace(" ", "")

    # Tokenize using regex
    tokens = re.findall(r'(\d+\.\d+|\d+|[-+*/^()]|\.|\-)', expr)

    # Check for invalid characters or malformed numbers
    for token in tokens:
        if token == '.' or token == '-':
            if len(tokens) == 1:
                raise ValueError("Malformed number")
            if tokens[0] == '-' and token == '-':
                raise ValueError("Malformed number")
            if tokens[0] == '.' and token == '.':
                raise ValueError("Malformed number")
        elif token == '-' and tokens[0] == '-':
            raise ValueError("Malformed number")
        elif token == '.' and tokens[0] == '.':
            raise ValueError("Malformed number")

    # Check for invalid tokens
    for token in tokens:
        if not (token.isdigit() or token == '.' or token == '-' or token in '+*/^()'):
            raise ValueError(f"Invalid character: {token}")

    return tokens
